const p = $json.properties || {};
const resumeProp = p['Résumé'] || {};
const resumeText = (resumeProp.rich_text && resumeProp.rich_text[0] && resumeProp.rich_text[0].plain_text) || '';
if (resumeText.trim()) {
  return [];
}
const titleProp = p['Nom de la tâche'] || {};
const title = (titleProp.title && titleProp.title[0] && titleProp.title[0].plain_text) || '';
const etiquettesProp = p['Étiquettes'] || {};
const etiquettes = etiquettesProp.multi_select || [];
const etiquette = etiquettes.length ? etiquettes[0].name : '';
return [{ json: { sujet: title.trim(), notion_page_id: $json.id, etiquette } }];

const results = $json.results || [];
const sujet = $('Contexte Notion (sujet)').first().json.sujet;
const pageId = $('Contexte Notion (sujet)').first().json.notion_page_id;
const lines = [];
let image_couverture_id = null;
const imageRe = /Image WordPress generee \(id=(\d+)\)/;
for (const block of results) {
  const type = block.type;
  const richText = block[type] && block[type].rich_text;
  if (!richText) continue;
  const text = richText.map(t => t.plain_text || '').join('');
  if (!text.trim()) continue;
  const m = text.match(imageRe);
  if (m) {
    if (image_couverture_id === null) image_couverture_id = parseInt(m[1], 10);
    continue;
  }
  lines.push(text.trim());
}
return [{ json: { sujet, notion_page_id: pageId, brief: lines.join('\n\n'), image_couverture_id } }];

