const research = $json.choices && $json.choices[0]
  ? $json.choices[0].message.content : '';
const citations = ($json.citations || []).map((c, i) => `[${i+1}] ${c}`).join('\n');
const sujet = $('Extraire brief').first().json.sujet;
const brief = $('Extraire brief').first().json.brief;
const pageId = $('Extraire brief').first().json.notion_page_id;
const image_couverture_id = $('Extraire brief').first().json.image_couverture_id;
const userPrompt = [
  'Sujet : ' + sujet,
  '',
  'Plan de recherche :',
  brief,
  '',
  'Recherche approfondie et sources :',
  research,
  '',
  'Sources :',
  citations
].join('\n');
return [{ json: { notion_page_id: pageId, sujet, image_couverture_id, user_prompt: userPrompt } }];

const content = $json.content && $json.content[0]
  ? $json.content[0].text : '';
const pageId = $('Preparer input Claude').first().json.notion_page_id;
const sujet = $('Preparer input Claude').first().json.sujet;
const image_couverture_id = $('Preparer input Claude').first().json.image_couverture_id || null;
const etiquette = $('Contexte Notion (sujet)').first().json.etiquette;

const CATEGORIE_MAP = {
  'Agro-alimentaire': 4,
  'Douanes & Logistiques': 2,
  'Certifications': 6,
  'Financements': 19,
  'Artisant & Textile': 1,
  'Etudes de cas PME': 5,
  'Page statiques': 1,
};
const categorie_wp = CATEGORIE_MAP[etiquette] || 1;

const metadata = { titre_wp: sujet, categorie_wp, image_couverture_id };

function chunk(str, size) {
  const parts = [];
  for (let i = 0; i < str.length; i += size) parts.push(str.substring(i, i + size));
  return parts.length ? parts : [''];
}
const htmlRichText = chunk(content, 2000).map(c => ({ type: 'text', text: { content: c } }));

const notion_blocks = {
  children: [
    { type: 'code', code: {
        language: 'json',
        rich_text: [{ type: 'text', text: { content: JSON.stringify(metadata, null, 2) } }]
    }},
    { type: 'heading_2', heading_2: { rich_text: [{ type: 'text', text: { content: 'Article' } }] } },
    { type: 'code', code: {
        language: 'html',
        rich_text: htmlRichText
    }},
  ]
};
return [{ json: { notion_page_id: pageId, notion_blocks } }];
